body:
When we are trying to get data from Barcode Scanner by read method, we are getting data chunks from Barcode that look like this:

![image](https://github.com/WICG/webhid/assets/59835690/ef77ddde-5d6b-492a-a5a1-0f292abfd696)

code example:

async function readUntilClosed(serialDevice, serialService) {
    let error = 'Unknown error';
    try {
        while (serialDevice.port.readable && serialDevice.port.writable && serialDevice.reading) {

            serialDevice.reader = serialDevice.port.readable.getReader();

            try {
                while (serialDevice.reading && serialDevice.port.readable) {
                    let { value, done } = await serialDevice.reader.read();
                    if (value && value.length > 0 && serialDevice.reading) {
                        console.log(value);
                        await callOnDataReceived(value, serialService);
                    }
                    if (done) {
                        break;
                    }
                }
            }
            catch (error) {
                error = error.message;
                console.log("Serial error: " + error.message);
            }
            finally {
                // Allow the serial port to be closed later.
                serialDevice.reader.releaseLock();
            }

            sleep(200);
        }
    } catch (error) {
        error = error.message;
        console.warn("Serial error: " + error.message);
    } 

    try {
        serialDevice.reader.cancel();
    }
    catch (error) {
        console.log("Serial error: " + error.message);
    }

    if (serialDevice.allowPortClosing) {
        try {
            await serialDevice.port.close();
            serialDevice.opened = false;
        }
        catch (error) {
            error = error.message;
            console.log("Serial error: " + error.message);
        }
    }

    if (serialDevice.reading) {
        serialService.invokeMethodAsync("OnSerialError", parseUsbDevice(serialDevice), error);
    }
}

Main question is this - is there any way to get full data in one go and, if not, is there any way to distinguish chunks from that exact barcode in that exact scan?

Also tried to analyze signals like dataSetReady, but they are all "Ready" and that was so unhelpfull.

Our Barcode Scannes is Honeywell Voyager 1450g and few others, problem is the same across the board.
